/**
 * Open a purchase-day fill-draw craps battle on the Craps table, focused on one wallet's run.
 *
 * The fill draw (CoinDrawBattle, audit 5790a946) is NOT a CrapsBattle field: there is no shared
 * shooter, no seats, no scheduled window and no progressive. Every drawn wallet plays its own dice
 * off the battle word, so a run is shown alone on the table — the table's leaderboard and opponent
 * felt stay empty rather than pretending other runs shared these rolls. The field's standing and
 * the pot travel in the entry label and the bounty marquee.
 *
 * The data path is chain-only and verified: `chainCoinDrawBattle` replays the battle in a worker
 * and returns `replay: null` if any logged figure disagrees. This module then decomposes the run
 * into roll frames with `replayCrapsSoloRun`, which must meet every ladder checkpoint again.
 */

import { replayCrapsSoloRun, CRAPS_REPLAY_BET_IDS, CRAPS_REPLAY_FLIP_WEI } from './replay-engine.js';
import { CRAPS_REPLAY_LEG_ORDER } from './replay-contract.js';
import {
  crapsReplaySoloFrames,
  crapsReplayRollsHex,
  loadCrapsReplayProfiles,
  protocolSeatLabel,
} from './replay-adapter.js';

export const COIN_DRAW_ENGINE_VERSION = 'coin-draw-battle-8b380ffe-v1';

const displayFlip = (wei) => (BigInt(wei) / CRAPS_REPLAY_FLIP_WEI).toString();
const normalAddress = (value) => {
  const address = String(value ?? '').trim().toLowerCase();
  return /^0x[0-9a-f]{40}$/.test(address) ? address : null;
};

function compactFlip(wei) {
  const whole = BigInt(wei ?? 0) / CRAPS_REPLAY_FLIP_WEI;
  const tiers = [[1_000_000_000n, 'B'], [1_000_000n, 'M'], [1_000n, 'K']];
  for (const [scale, suffix] of tiers) {
    if (whole >= scale) {
      const tenths = (whole * 10n) / scale;
      return `${tenths / 10n}${tenths % 10n ? `.${tenths % 10n}` : ''}${suffix}`;
    }
  }
  return whole.toString();
}

/** Why the run stopped, in the table's terms: a capped run pays its bankroll, like a goal. */
function capLabel(run) {
  return run.totalRolls >= 200 ? 'ROLL CAP' : 'SHOOTER CAP';
}

/**
 * The table options for one replayed run. `battle` is `chainCoinDrawBattle`'s result with a
 * verified `replay`; `index` is the run's first-drawn position.
 */
export function coinDrawRunTableOptions(battle, index, { profiles = null } = {}) {
  const replay = battle?.replay;
  const run = replay?.runs?.[index];
  if (!run) throw new TypeError(`Fill-draw run ${index} was not replayed`);
  const chip = BigInt(replay.chipFlip);
  const boardWei = Object.fromEntries(CRAPS_REPLAY_LEG_ORDER.map((leg) => [leg, BigInt(run.board[leg]) * CRAPS_REPLAY_FLIP_WEI]));
  const betId = `${battle.key}:${index}`;
  const trace = replayCrapsSoloRun({
    betId, player: run.player, boardWei, hands: run.hands, ladderWei: run.ladderWei,
    handsPlayed: run.handsPlayed, totalRolls: run.totalRolls, stop: run.stop === 'goal' ? 'goal' : 'bust',
    survivals: run.survivals, boosts: [],
  });
  const frames = [...crapsReplaySoloFrames(trace)];
  if (run.stop === 'capped' && frames.length) {
    // The engine calls a capped stop a bust only because it came before the goal; the battle
    // pays the bankroll it held. Close the rack as a completed run instead.
    const last = frames.at(-1);
    frames[frames.length - 1] = Object.freeze({ ...last, terminal: '', viewerTerminal: '',
      label: `${String(last.label).replace(/ · (RUN ENDED|SURVIVAL LOST)$/, '')} · ${capLabel(run)}` });
  }
  const identity = profiles?.get?.(run.player) ?? null;
  const pot = BigInt(replay.potWei);
  const high = run.ladderWei.reduce((best, value) => (BigInt(value) > best ? BigInt(value) : best), BigInt(run.bankrollInWei));
  const units = Number(run.units);
  return Object.freeze({
    screen: 'battle',
    tableResolved: true,
    showResolution: frames.length > 0,
    tableIndex: battle.key,
    battleSlot: battle.key,
    replayLane: 'main',
    entryKind: 'custom',
    entryLabel: `FILL-DRAW BATTLE · RANK ${run.rank}/${replay.runs.length}${units > 1 ? ` · ${units} UNITS` : ''}`,
    viewerBetId: betId,
    viewerPlayer: run.player,
    originalViewerBetId: betId,
    viewerLabel: protocolSeatLabel(run.player) || identity?.name || null,
    viewerDiscordPfp: identity?.avatar || null,
    viewerResult: Object.freeze({
      stop: run.stop === 'capped' ? null : run.stop,
      handsPlayed: run.handsPlayed,
      exitRoll: Math.max(1, run.totalRolls),
      rawEndingFlip: displayFlip(run.bankrollOutWei),
      highPointFlip: displayFlip(high),
      standing: 0,
      // What the chain credited for the run, all units, excluding the pot.
      runPayoutWei: run.paidWei,
    }),
    fieldEntrants: replay.runs.length,
    rankTimeline: Object.freeze([]),
    entryMultiple: 1,
    bets: Object.freeze(Object.fromEntries(CRAPS_REPLAY_BET_IDS.map((id, i) => [id, Number(BigInt(run.board[CRAPS_REPLAY_LEG_ORDER[i]]) / chip)]))),
    playedFlip: (chip * 10n).toString(),
    battleStakeFlip: '0',
    // The pot is what the best paid run wins on top of its own payout: the battle's bounty.
    bountyPoolWei: pot > 0n ? pot.toString() : null,
    addedFlipWei: null,
    bankrollFlip: displayFlip(run.bankrollInWei),
    goalFlip: displayFlip(run.goalWei),
    rolls: crapsReplayRollsHex(trace.hands.map((hand) => hand.events.map((event) => ({ d1: event.d1, d2: event.d2 })))),
    resolutionHands: Object.freeze(frames),
    shooterTimeline: Object.freeze([]),
    otherPlayers: Object.freeze([]),
    leaderboardTimeline: Object.freeze([]),
    battleWonByViewer: run.isWinner === true,
    battlePayoutWei: run.isWinner === true && pot > 0n ? pot.toString() : null,
    replayDigest: `${battle.key}:${battle.transactionHash ?? ''}`,
    replayEngineVersion: COIN_DRAW_ENGINE_VERSION,
  });
}

/** One line for the jackpot centre when a replay cannot be shown: the chain's own result. */
export function coinDrawChainResultLine(battle, player) {
  const address = normalAddress(player);
  const row = battle?.runs?.find?.((entry) => normalAddress(entry.player) === address);
  if (!row) return 'This wallet was not drawn into the battle.';
  const paid = BigInt(row.paid);
  return `Your run: ${row.rolls} rolls, ended on ${compactFlip(row.bankrollOut)} FLIP, ${paid > 0n ? `paid ${compactFlip(paid)} FLIP` : 'busted'}.`;
}

async function readyTable(doc, timeoutMs) {
  const table = doc?.querySelector?.('app-craps-table');
  if (table?.open) return table;
  const defined = globalThis.customElements?.whenDefined?.('app-craps-table');
  if (!defined) return null;
  await Promise.race([defined, new Promise((resolve) => setTimeout(resolve, timeoutMs))]);
  const upgraded = doc?.querySelector?.('app-craps-table');
  return upgraded?.open ? upgraded : null;
}

/**
 * Load the day's battle and open `player`'s run on the page's Craps table.
 * @returns {Promise<{ ok: boolean, message?: string, battle?: object }>}
 */
export async function openCoinDrawRun({
  day,
  player,
  opener = null,
  doc = globalThis.document,
  load = null,
  loadProfiles = loadCrapsReplayProfiles,
  tableTimeoutMs = 4_000,
} = {}) {
  const address = normalAddress(player);
  if (!address) return { ok: false, message: 'Pick a player to watch their battle run.' };
  const loader = load ?? (await import('../chain/coin-draw.js')).chainCoinDrawBattle;
  const battle = await loader(day);
  const index = battle.runs.findIndex((row) => normalAddress(row.player) === address);
  if (index < 0) return { ok: false, message: 'This wallet was not drawn into the battle.', battle };
  if (!battle.replay) {
    return { ok: false, message: `Battle replay unavailable. ${coinDrawChainResultLine(battle, address)}`, battle };
  }
  const table = await readyTable(doc, tableTimeoutMs);
  if (!table) return { ok: false, message: 'The Craps table is still loading. Try again in a moment.', battle };
  let profiles = null;
  try { profiles = await loadProfiles([address]); } catch (_error) { /* identity is decoration */ }
  table.open(coinDrawRunTableOptions(battle, index, { profiles }), opener);
  return { ok: true, battle };
}
